        elif name in {"DROP", "BRANCH", "FREE", "HALT"}:
            delta = -1
        elif name == "STORE":
            delta = -2
        elif name in {"ADD", "SUB", "EQ", "LT", "LE", "AND", "OR"}:
            delta = -1
        if name == "CALL":
            ret_delta = 1
        elif name == "RETURN":
            ret_delta = -1
